    return clone(this.ledger.outputs[index]);
}

writeAuditLog(entry) {
    this.ledger.audit_logs.push({ id: entry.id || `audit_${crypto.randomUUID()}`, created_at: nowIso(), ...entry });
    this._persist();
    return clone(this.ledger.audit_logs[this.ledger.audit_logs.length - 1]);
}

